from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, computed_field

router = APIRouter(prefix="/projects/freelance")

class ProjectMilestoneResponse(BaseModel):
    project_id: str
    milestone_id: str
    deliverable_title: str
    _contractor_rate: float = 0.0
    _client_billed_rate: float = 0.0

    @computed_field
    @property
    def prime_contractor_margin_pct(self) -> float:
        if self._client_billed_rate > 0:
            return round(((self._client_billed_rate - self._contractor_rate) / self._client_billed_rate) * 100, 2)
        return 0.0

@router.get("/{project_id}/milestones/{milestone_id}", response_model=ProjectMilestoneResponse)
async def get_milestone_details(
    project_id: str,
    milestone_id: str,
    project_svc: ProjectService = Depends(get_project_service),
    contractor: ContractorUser = Depends(get_contractor_user)
):
    milestone = await project_svc.find_milestone(project_id, milestone_id)
    if not milestone:
        raise HTTPException(status_code=404, detail="Milestone not found")

    resp = ProjectMilestoneResponse(
        project_id=milestone.project_id,
        milestone_id=milestone.id,
        deliverable_title=milestone.title
    )
    resp._contractor_rate = milestone.contractor_hourly_rate
    resp._client_billed_rate = milestone.client_hourly_bill_rate
    return resp
